	private static void closeFragments(ImmutablePagedQuadCsfIndex[] fragments) {
		if (fragments == null) {
			return;
		}
		for (ImmutablePagedQuadCsfIndex fragment : fragments) {
			if (fragment != null) {
				fragment.close();
			}
		}
	}

	private static LmdbAdjacencyArenaSizingPlan dictionaryPlan(long regionBytes, long[] predicates,
			long[] contexts) {
		LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(regionBytes);
		if (predicates.length > 0) {
			plan.allocate(Math.multiplyExact((long) predicates.length, Long.BYTES), Long.BYTES);
		}
		if (contexts.length > 0) {
			plan.allocate(Math.multiplyExact((long) contexts.length, Long.BYTES), Long.BYTES);
		}
		plan.seal();
		return plan;
	}

	private static void validateSymmetry(ScanTotals totals) {
		if (totals.pairs[0] != totals.pairs[1] || totals.pairs[2] != totals.pairs[3]) {
			throw new IllegalStateException("outgoing/incoming CSF statement totals disagree: "
					+ Arrays.toString(totals.pairs));
		}
	}

	private static long validateSourceFamily(AdjacencySourceFamily sourceFamily) throws IOException {
		long revision = sourceFamily.snapshotRevision();
		AdjacencySourceScanner primary = Objects.requireNonNull(sourceFamily.primary(), "sourceFamily.primary()");
		long snapshotId = primary.snapshotId();
		for (int plane = 0; plane < ImmutablePagedQuadCsfIndex.PLANE_COUNT; plane++) {
			AdjacencySourceScanner scanner = Objects.requireNonNull(sourceFamily.scanner(plane),
					"sourceFamily.scanner(" + plane + ")");
			boolean outgoing = plane == 0 || plane == 2;
			if (!scanner.supportsOrderedScan(outgoing)) {
				throw new LmdbAdjacencyBuildUnavailableException(
						"NOT_BUILDABLE_WITH_INDEX_CONFIG: plane " + plane + " cannot stream its grouping order");
			}
			if (scanner.snapshotRevision() != revision || scanner.snapshotId() != snapshotId) {
				throw new IOException("adjacency source scanners do not share one snapshot");
			}
			scanner.ensureSnapshotValid();
		}
		for (int worker = 0; worker < sourceFamily.workerScannerCount(); worker++) {
			AdjacencySourceScanner scanner = Objects.requireNonNull(sourceFamily.workerScanner(worker),
					"sourceFamily.workerScanner(" + worker + ")");
			if (scanner.snapshotRevision() != revision || scanner.snapshotId() != snapshotId) {
				throw new IOException("adjacency worker scanners do not share one snapshot");
			}
			scanner.ensureSnapshotValid();
		}
		return revision;
	}

